SET default_transaction_read_only = on;
\copy (SELECT dc.ticker, dc.trade_date, dc.open_price, dc.high_price, dc.low_price, dc.close FROM mi_daily_closes dc WHERE dc.trade_date >= DATE '2026-06-01' AND dc.open_price IS NOT NULL AND dc.high_price IS NOT NULL AND dc.low_price IS NOT NULL AND dc.ticker IN (SELECT ticker FROM mi_live_trades WHERE account_mode = 'live' AND signal_type = 'magna53' AND filled_at IS NOT NULL AND (filled_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-08-16' UNION SELECT ticker FROM mi_orb_shadow_trades WHERE bar_size_minutes = 5 AND NOT quarantined AND signal_type = 'magna53' AND alert_date >= DATE '2026-08-17') ORDER BY dc.ticker, dc.trade_date) TO STDOUT WITH CSV HEADER
